script.inlineScript:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    //this function checks for props_details of all blocks at all levels.
    //the value of show field is toggled on button click if it is defined.
    const aceBlocks = api.state.aceContentBlocks;
    toggleShow(aceBlocks);

    function toggleShow(blocks) {
        blocks.forEach(function(block) {
            if (block.props_details.show !== undefined) {
                block.props_details.show = !block.props_details.show;
            }
            if (block.children.length > 0) toggleShow(block.children);
        });

    }
    return {
        propName: "aceContentBlocks",
        value: aceBlocks
    };
}
